package app.kinnect.live;
import android.widget.TextView;import android.graphics.drawable.Drawable;
/** Consistent outline vectors. Numeric speed and duration controls stay numeric. */
final class EditorIcons {
 static String alias(String id){switch(id){case "×":return "close";case "✧":case "✨":return "beauty";case "🕶":return "sticker";case "◈":return "filter";case "✂":return "cut";case "1×":return "speed";case "♫":return "music";case "T":return "text";case "↶":return "undo";case "↷":return "redo";case "◐":return "compare";case "▷":return "play";case "⇩":return "export";case "✓":return "check";case "○":return "none";case "🌸":return "blush";case "🎀":return "beauty";case "👀":return "eyes";case "💋":return "lips";}return id;}
 static String shared(String id){switch(alias(id)){case "close":return "x";case "beauty":return "sparkles";case "sticker":return "smile";case "filter":return "sliders_horizontal";case "cut":return "scissors";case "music":return "music_2";case "undo":return "undo_2";case "redo":return "redo_2";case "play":return "play";case "check":return "check";case "delete":return "trash_2";case "flip":return "switch_camera";case "crop":return "crop";case "export":return "download";case "duplicate":return "copy";}return null;}
 static Drawable drawable(android.content.Context c,String id,int color){String common=shared(id);if(common!=null&&WebIcons.resolve(c,common)!=0){Drawable d=WebIcons.load(c,common);d.setTint(color);return d;}int resource=c.getResources().getIdentifier("ic_flow_editor_"+alias(id),"drawable",c.getPackageName());if(resource==0)resource=c.getResources().getIdentifier("ic_editor_"+alias(id),"drawable",c.getPackageName());if(resource==0)return null;Drawable d=c.getDrawable(resource).mutate();d.setTint(color);return d;}
 static boolean apply(TextView view,String id,int size,int color){Drawable d=drawable(view.getContext(),id,color);if(d==null)return false;int px=Math.round(size*view.getResources().getDisplayMetrics().density);d.setBounds(0,0,px,px);view.setText("");view.setCompoundDrawables(d,null,null,null);view.setCompoundDrawablePadding(0);return true;}
}
